import{_ as n,C as o,o as i,c as l,aj as t,G as s,j as r,a as h}from"./chunks/framework.BwH0p-pt.js";const b=JSON.parse('{"title":"Users","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/settings/users.md","filePath":"3.0/settings/users.md","lastUpdated":1785836850000}'),d={name:"3.0/settings/users.md"};function g(p,e,c,u,m,f){const a=o("ImagePopup");return i(),l("div",null,[e[0]||(e[0]=t('<h1 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h1><p>It refer to the individuals who interact with the system, including roles such as product managers, content creators, marketers, and administrators, each with specific permissions and access levels for managing and maintaining product data.</p><h3 id="steps-to-create-users-in-unopim" tabindex="-1">Steps to create Users in UnoPim <a class="header-anchor" href="#steps-to-create-users-in-unopim" aria-label="Permalink to &quot;Steps to create Users in UnoPim&quot;">​</a></h3><p><strong>Step 1:</strong> It can be set on the admin panel by going to <strong>Settings → Users</strong>. Here you can create new users by clicking on the button <strong>Create User</strong> as shown in below image.</p>',4)),s(a,{src:"/assets/3.0/images/settings/createUser.png",alt:"Create User"}),e[1]||(e[1]=t('<p><strong>Step 2:</strong> Now add the below fields</p><ol><li><p><strong>Name -</strong> Enter the name of the User.</p></li><li><p><strong>Email -</strong> Enter the Email of the User.</p></li><li><p><strong>Password -</strong> Enter the password of the user.</p></li><li><p><strong>UI Locale -</strong> Select the language of the admin interface for this user.</p></li><li><p><strong>Catalog Locale -</strong> The language this user writes catalog content in. Separate from their interface language — see <a href="#catalog-locale-and-default-channel">Catalog Locale and Default Channel</a> below.</p></li><li><p><strong>Default Channel -</strong> The channel UnoPim opens for this user by default.</p></li><li><p><strong>Timezone -</strong> Select the timezone as per the user.</p></li><li><p><strong>Role -</strong> Select the role of the user. You can only assign roles you are allowed to assign — see <a href="#role-assignment">Role assignment</a> below.</p></li><li><p><strong>Status -</strong> Enable the status of the user.</p></li><li><p><strong>Image -</strong> You can also add the image of the user. If no image is uploaded, the user&#39;s Gravatar picture can be shown instead — see <a href="#profile-pictures-and-gravatar">Profile pictures</a> below.</p></li></ol><p>At Last, click on <strong>Save User</strong> button.</p>',3)),s(a,{src:"/assets/3.0/images/settings/saveUser.png",alt:"User"}),e[2]||(e[2]=r("p",null,[r("strong",null,"Step 3:"),h(" Now a new user is created successfully in the user datagrid as shown in the below image.")],-1)),s(a,{src:"/assets/3.0/images/settings/userGrid.png",alt:"User Grid"}),e[3]||(e[3]=t('<h2 id="catalog-locale-and-default-channel" tabindex="-1">Catalog Locale and Default Channel <a class="header-anchor" href="#catalog-locale-and-default-channel" aria-label="Permalink to &quot;Catalog Locale and Default Channel&quot;">​</a></h2><p>Every user carries two personal catalog settings, separate from the interface language:</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Catalog Locale</strong></td><td>The language UnoPim opens when this user edits a product, and the language product names appear in on their grids.</td></tr><tr><td><strong>Default Channel</strong></td><td>The channel selected for this user by default when editing products and browsing grids.</td></tr></tbody></table><p>These settings follow the user everywhere: product editing, product grids, and background jobs that run on the user&#39;s behalf (such as imports and exports) all use them. Users can change their own values under <strong>My Account</strong>; administrators can set them here.</p><h2 id="profile-pictures-and-gravatar" tabindex="-1">Profile pictures and Gravatar <a class="header-anchor" href="#profile-pictures-and-gravatar" aria-label="Permalink to &quot;Profile pictures and Gravatar&quot;">​</a></h2><p>When a user has no uploaded profile image, UnoPim shows the <a href="https://gravatar.com" target="_blank" rel="noreferrer">Gravatar</a> picture linked to their email address. Each user can switch this off with the <strong>Use Gravatar image</strong> option — with it off and no image uploaded, UnoPim shows their initials instead.</p><h2 id="role-assignment" tabindex="-1">Role assignment <a class="header-anchor" href="#role-assignment" aria-label="Permalink to &quot;Role assignment&quot;">​</a></h2><p>You can only assign roles that your own role permits. An administrator cannot grant a role that holds permissions they do not have themselves, and only an all-access administrator can assign another all-access role.</p><h2 id="changing-a-password" tabindex="-1">Changing a password <a class="header-anchor" href="#changing-a-password" aria-label="Permalink to &quot;Changing a password&quot;">​</a></h2><p>Password confirmation is now only requested when you are actually changing a password. Updating a user&#39;s name, locale, or other profile details no longer asks you to confirm a password.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>API integrations get their own automatic &quot;robot&quot; users behind the scenes. Robot users never appear in this list and cannot sign in to the admin panel — the Users grid shows only real people.</p></div><p>So by this you can easily create a Users in UnoPim.</p>',12))])}const _=n(d,[["render",g]]);export{b as __pageData,_ as default};
